#!/usr/bin/env python3
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).parent / "generated" / "jiudi19"
FONT = "/System/Library/Fonts/AppleSDGothicNeo.ttc"

def f(n, bold=True): return ImageFont.truetype(FONT, n, index=2 if bold else 0)
def label(im, x, y, s, n=44):
    d=ImageDraw.Draw(im,"RGBA"); b=d.multiline_textbbox((x,y),s,font=f(n),anchor="mm",align="center",spacing=5)
    d.rounded_rectangle((b[0]-15,b[1]-10,b[2]+15,b[3]+10),radius=12,fill=(8,10,14,215),outline=(244,211,128,235),width=3)
    d.multiline_text((x,y),s,font=f(n),fill="white",anchor="mm",align="center",spacing=5,stroke_width=2,stroke_fill="black")
def finish(name,title,items):
    p=ROOT/name; im=Image.open(p).convert("RGB").resize((2400,1600),Image.Resampling.LANCZOS).convert("RGBA")
    d=ImageDraw.Draw(im,"RGBA"); d.rectangle((0,0,2400,125),fill=(5,7,10,235)); d.text((1200,63),title,font=f(62),fill="white",anchor="mm",stroke_width=2,stroke_fill="black")
    for x,y,s,n in items: label(im,x,y,s,n)
    im.convert("RGB").save(p)

